files = repo.list("logs")
content = repo.read("logs/service.log", missing_ok=True)
if content == None:
    return {"files": files, "content": None}
lines = content.split("\n")
hits = [i for i, l in enumerate(lines) if "ALERT" in l]
out = []
for i in hits:
    out.append({
        "line_number": i + 1,
        "context": lines[max(0, i-1):i+2],
    })
return {"files": files, "total_lines": len(lines), "hits": out}
